#!/usr/bin/env bash
# Direct Corelink-only secret rotation; plan mode is completely inert.
set -euo pipefail
umask 077
readonly ACK1='ACK-DIRECT-CORELINK-ROTATION-LIVE-20260908' ACK2='ACK-FORWARD-ONLY-RECOVERY-PAIR-LIVE-20260908'
PACKAGE_ROOT="$(cd -- "${BASH_SOURCE[0]%/*}/.." && pwd -P)"; readonly PACKAGE_ROOT
MODE=plan ATTEMPT=primary ROOT='' COMMIT='' SPAWN_VERSION='' FABRICD_VERSION='' SPAWN_APP='' FABRICD_APP='' CANARY_IMAGE='' OLD_TOKEN_FILE='' LIVE_ACK='' RECOVERY_ACK='' MOCK_WRANGLER='' CURL_BIN=curl VERIFY_BIN=''
OOB_DIR="$HOME/.corelink/rotation-b2-20260908"; EVIDENCE_DIR="$OOB_DIR/evidence-direct"; FLEET_KEY_FILE="$OOB_DIR/fleet-busy-read-key"; CANARY_PAT_FILE="$OOB_DIR/corelink-canary-tenant-pat"
SPAWN_URL='https://corelink-spawn-worker.gmhelmold.workers.dev'; FABRICD_URL='https://corelink-fabricd.gmhelmold.workers.dev'
die(){ printf 'REFUSED: %s\n' "$*" >&2; exit 2; }
while [ "$#" -gt 0 ]; do case "$1" in
--mode) MODE="${2:?}";shift 2;;--attempt) ATTEMPT="${2:?}";shift 2;;--live-ack) LIVE_ACK="${2:?}";shift 2;;--recovery-ack) RECOVERY_ACK="${2:?}";shift 2;;--integration-root) ROOT="${2:?}";shift 2;;--expected-commit) COMMIT="${2:?}";shift 2;;--spawn-version) SPAWN_VERSION="${2:?}";shift 2;;--fabricd-version) FABRICD_VERSION="${2:?}";shift 2;;--spawn-app-id) SPAWN_APP="${2:?}";shift 2;;--fabricd-app-id) FABRICD_APP="${2:?}";shift 2;;--canary-image) CANARY_IMAGE="${2:?}";shift 2;;--oob-dir) OOB_DIR="${2:?}";shift 2;;--evidence-dir) EVIDENCE_DIR="${2:?}";shift 2;;--fleet-key-file) FLEET_KEY_FILE="${2:?}";shift 2;;--canary-pat-file) CANARY_PAT_FILE="${2:?}";shift 2;;--old-token-file) OLD_TOKEN_FILE="${2:?}";shift 2;;--mock-wrangler) MOCK_WRANGLER="${2:?}";shift 2;;--curl-bin) CURL_BIN="${2:?}";shift 2;;--verify-bin) VERIFY_BIN="${2:?}";shift 2;;*) die "unknown argument $1";;esac;done
case "$MODE:$ATTEMPT" in plan:*|mock:primary|mock:recovery|live:primary|live:recovery);;*)die 'invalid mode/attempt';;esac
if [ "$MODE" = plan ]; then printf '%s\n' 'PLAN ONLY: no file is read, no command is run, no secret is generated.' 'Live path: lock, baseline, freeze, forward cutover, proof, canary, refreeze.';exit 0;fi
[ "$MODE" != live ] || { [ "$LIVE_ACK" = "$ACK1" ] && [ "$RECOVERY_ACK" = "$ACK2" ] || die 'both exact live acknowledgements required'; }
[ "$MODE" != mock ] || [ -x "$MOCK_WRANGLER" ] || die 'mock requires mock wrangler'
[ -n "$VERIFY_BIN" ] || VERIFY_BIN="$PACKAGE_ROOT/bin/verify-close-attestation.mjs"
[ -x "$VERIFY_BIN" ] || die 'verifier must be executable'
safe_file(){ [ -f "$1" ]&&[ ! -L "$1" ]&&[ "$(stat -f '%OLp' "$1")" = 600 ]; };safe_dir(){ [ -d "$1" ]&&[ ! -L "$1" ]&&[ "$(stat -f '%OLp' "$1")" = 700 ]; };sha(){ openssl dgst -sha256 -r "$1"|awk '{print $1}';};record(){ printf '%s\n' "$*">>"$EVIDENCE_DIR/events.log";}
run_wrangle(){ if [ "$MODE" = mock ];then "$MOCK_WRANGLER" "$@";return;fi;local t;t="$(npx --no-install wrangler auth token --json|jq -er '.token // .access_token // .')"||die 'wrangler OAuth unavailable';[[ "$t" =~ ^[A-Za-z0-9._~+/=-]{16,}$ ]]||die 'bad OAuth';CLOUDFLARE_API_TOKEN="$t" npx --no-install wrangler "$@";}
# A secret becomes curl configuration only through an inherited FD; never argv,
# a persistent file, output, evidence, or a child-process command line.
curl_secret(){ local f="$1";shift;safe_file "$f"||die 'secret must be nofollow 0600';local s;s="$(<"$f")";[ -n "$s" ]||die 'empty secret';"$CURL_BIN" --fail --silent --show-error --config <(printf '%s\n' "header = \"authorization: Bearer $s\"") "$@";}
SPAWN_CONFIG='' FABRICD_CONFIG='' LOCK='' LOCKED=0 FINAL_FROZEN=0
refreeze(){ run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate >/dev/null;run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 >/dev/null;record 'freeze=fabricd_then_spawn';}
cleanup(){ local rc=$?;if [ "$LOCKED" = 1 ]&&[ "$FINAL_FROZEN" != 1 ];then refreeze >/dev/null 2>&1||true;record 'exit_refreeze=attempted';fi;[ -z "$LOCK" ]||rmdir "$LOCK" 2>/dev/null||true;exit "$rc";};trap cleanup EXIT
[ -n "$ROOT" ]&&[ -n "$COMMIT" ]&&[ -n "$SPAWN_VERSION" ]&&[ -n "$FABRICD_VERSION" ]&&[ -n "$SPAWN_APP" ]&&[ -n "$FABRICD_APP" ]&&[ -n "$CANARY_IMAGE" ]&&[ -n "$OLD_TOKEN_FILE" ]||die 'missing pins';[[ "$COMMIT" =~ ^[a-f0-9]{40}$ && "$CANARY_IMAGE" =~ @sha256:[a-f0-9]{64}$ ]]||die 'malformed pin';safe_dir "$OOB_DIR";safe_file "$FLEET_KEY_FILE";safe_file "$CANARY_PAT_FILE";safe_file "$OLD_TOKEN_FILE"
LOCK="$OOB_DIR/.direct-rotation.lock";mkdir "$LOCK" 2>/dev/null||die 'exclusive rotation lock held';chmod 700 "$LOCK";LOCKED=1;SPAWN_CONFIG="$ROOT/deploy/cloudflare/wrangler.jsonc";FABRICD_CONFIG="$ROOT/deploy/cloudflare-fabricd/wrangler.jsonc"
if [ "$(git -C "$ROOT" rev-parse HEAD)" != "$COMMIT" ] || ! git -C "$ROOT" diff --quiet || ! git -C "$ROOT" diff --cached --quiet;then die 'source is not clean exact commit';fi;for p in deploy/cloudflare/wrangler.jsonc deploy/cloudflare-fabricd/wrangler.jsonc;do if ! git -C "$ROOT" ls-files --error-unmatch "$p">/dev/null || ! git -C "$ROOT" cat-file -e "$COMMIT:$p";then die 'canonical config untracked';fi;done
mkdir -p "$EVIDENCE_DIR";chmod 700 "$EVIDENCE_DIR";:>"$EVIDENCE_DIR/events.log";chmod 600 "$EVIDENCE_DIR/events.log";grep -Fq "$CANARY_IMAGE" "$SPAWN_CONFIG"||die 'canary image absent from canonical config'
fleet="$(curl_secret "$FLEET_KEY_FILE" "$SPAWN_URL/internal/v1/fleet/busy")"||die 'fleet read failed';printf '%s' "$fleet"|jq -e '(.busy|tonumber)==0 and (.unverifiable|tonumber)==0' >/dev/null||die 'fleet busy/active_count/unverifiable nonzero'
sd="$(run_wrangle deployments list --name corelink-spawn-worker --json)";fd="$(run_wrangle deployments list --name corelink-fabricd --json)";printf '%s' "$sd"|jq -e --arg x "$SPAWN_VERSION" 'sort_by(.created_on//"")|last|.versions[0].version_id==$x'>/dev/null||die 'spawn version mismatch';printf '%s' "$fd"|jq -e --arg x "$FABRICD_VERSION" 'sort_by(.created_on//"")|last|.versions[0].version_id==$x'>/dev/null||die 'fabricd version mismatch'
si="$(run_wrangle containers info "$SPAWN_APP")";fi="$(run_wrangle containers info "$FABRICD_APP")";printf '%s' "$si"|grep -Fq "$CANARY_IMAGE"||die 'provider spawn image mismatch';fimage="$(grep -Eo 'registry[^" ]+@sha256:[a-f0-9]{64}' "$FABRICD_CONFIG"|tail -1)";if [ -z "$fimage" ] || ! printf '%s' "$fi"|grep -Fq "$fimage";then die 'provider fabricd image mismatch';fi;record "baseline=commit:$COMMIT spawn_config:$(sha "$SPAWN_CONFIG") fabricd_config:$(sha "$FABRICD_CONFIG") spawn_version:$SPAWN_VERSION fabricd_version:$FABRICD_VERSION"
run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1>/dev/null;run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate>/dev/null;record 'freeze=spawn_then_fabricd'
mksecret(){ local d="$1" t;[ ! -e "$d" ]&&[ ! -L "$d" ]||die 'forward-only secret exists';t="$(mktemp "$OOB_DIR/.rotation.XXXXXXXX")";chmod 600 "$t";openssl rand -base64 32 > "$t";safe_file "$t"||die 'secret mode';ln "$t" "$d"||die 'atomic nofollow secret commit failed';rm -f "$t";safe_file "$d"||die 'secret commit mode';}
pseed="$OOB_DIR/primary.fabric-signing-seed.b64";ptok="$OOB_DIR/primary.spawn-token.b64";rseed="$OOB_DIR/recovery.fabric-signing-seed.b64";rtok="$OOB_DIR/recovery.spawn-token.b64";if [ "$ATTEMPT" = primary ];then mksecret "$pseed";mksecret "$ptok";mksecret "$rseed";mksecret "$rtok";seed="$pseed";tok="$ptok";else safe_file "$pseed";safe_file "$ptok";safe_file "$rseed";safe_file "$rtok";seed="$rseed";tok="$rtok";fi
run_wrangle secret put CLOUDFLARE_SPAWN_AUTH_TOKEN --config "$SPAWN_CONFIG"<"$tok";run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1>/dev/null;run_wrangle secret put FABRIC_SIGNING_KEY --config "$FABRICD_CONFIG"<"$seed";run_wrangle secret put CLOUDFLARE_SPAWN_AUTH_TOKEN --config "$FABRICD_CONFIG"<"$tok";run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:1 --containers-rollout=immediate>/dev/null
keys="$($CURL_BIN --fail --silent --show-error "$FABRICD_URL/v1/attestation/key")";printf '%s' "$keys"|jq -e '(.keys|type=="array" and length==1)and.keys[0].expires_ms==null'>/dev/null||die 'not exact one selected key'
curl_secret "$tok" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST' 'data = "{}"' 'output = "/dev/null"' 'write-out = "%{http_code}"') "$SPAWN_URL/v1/spawn"|grep -qx 503||die 'new token proof';curl_secret "$OLD_TOKEN_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST' 'data = "{}"' 'output = "/dev/null"' 'write-out = "%{http_code}"') "$SPAWN_URL/v1/spawn"|grep -qx 401||die 'old token proof'
record 'release_transition=marked_before_first_unfreeze';run_wrangle deploy --config "$SPAWN_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:0>/dev/null;run_wrangle deploy --config "$FABRICD_CONFIG" --keep-vars --var FABRIC_ADMISSION_PAUSED:0 --containers-rollout=immediate>/dev/null
payload="$(jq -nc --arg image "$CANARY_IMAGE" '{image_digest:$image,net_policy:"isolated",tmp_root:"/work/tmp",expiry_ms:60000}')";acquire="$(curl_secret "$CANARY_PAT_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST') --data "$payload" "$FABRICD_URL/v1/leases")"||die 'canary acquire';lease="$(printf '%s' "$acquire"|jq -er '.lease.lease_id')"||die 'missing .lease.lease_id';close="$(curl_secret "$CANARY_PAT_FILE" --config <(printf '%s\n' 'header = "content-type: application/json"' 'request = POST') --data '{"status":"succeeded"}' "$FABRICD_URL/v1/leases/$lease/close")"||die 'canary close';printf '%s' "$close"|jq -e --arg l "$lease" '.lease_id==$l and .released==true and .capture_incomplete==false'>/dev/null||die 'close teardown proof';printf '%s' "$close"|"$VERIFY_BIN" "$keys"||die 'fresh Corelink v1/v2 verifier';refreeze;FINAL_FROZEN=1;record 'outcome=complete_final_frozen'
